 let undo=null,dragId='',ignoreClickUntil=0;const dragAnimations=new Set();
 function animateOrder(before,moved){if(!root.FolioMotion?.allowed())return;const playful=document.documentElement.dataset.motion==='full'&&document.documentElement.dataset.theme!=='yotsuba';for(const node of document.querySelectorAll('#grid>[data-layout-id]')){const old=before.get(node.dataset.layoutId),now=node.getBoundingClientRect();if(!old)continue;const scale=now.width/node.offsetWidth||1,dx=(old.left-now.left)/scale,dy=(old.top-now.top)/scale;if(!dx&&!dy&&node.dataset.layoutId!==moved)continue;const animation=node.animate([{transform:`translate(${dx}px,${dy}px) scale(${playful&&node.dataset.layoutId===moved?.97:1})`,opacity:.7},{transform:'translate(0,0) scale(1)',opacity:1}],{duration:playful?360:180,easing:'cubic-bezier(.2,.8,.2,1)'});dragAnimations.add(animation);animation.finished.catch(()=>{}).finally(()=>dragAnimations.delete(animation));}}
 const positions=()=>new Map([...document.querySelectorAll('#grid>[data-layout-id]')].map(n=>[n.dataset.layoutId,n.getBoundingClientRect()]));
 new MutationObserver(()=>{if(!root.FolioMotion?.allowed()){for(const a of dragAnimations)a.cancel();dragAnimations.clear();}}).observe(document.documentElement,{attributes:true,attributeFilter:['data-motion','data-ui-motion']});
 const library=document.createElement('div');library.className='browse-controls library-browse-controls';$('.toolbar').before(library);library.append($('.toolbar'));
 const filters=document.createElement('details');filters.className='browse-filters';filters.innerHTML='<summary>Filters <span class="browse-filter-count"></span></summary><div class="browse-filter-body"></div>';library.append(filters);for(const selector of ['#tabs','#collection-bar','.facet-filters'])filters.lastElementChild.append($(selector));
