 const tools=document.createElement('div');tools.className='custom-layout-tools';tools.hidden=true;tools.innerHTML='<span>Drag a tile to arrange, or use move buttons.</span><form id="divider-form"><label class="sr-only" for="divider-title">Divider title</label><input id="divider-title" maxlength="80" placeholder="New section name" required><button type="submit">＋ Divider</button></form><button type="button" id="layout-reset">Reset custom order</button><button type="button" id="layout-undo" hidden>Undo layout change</button><span class="sr-only" id="layout-status" role="status"></span>';library.append(tools);
 const search=document.createElement('div');search.className='browse-controls search-browse-controls';$('#live-form').before(search);search.append($('#live-form'));
 const searchFilters=document.createElement('details');searchFilters.className='browse-filters';searchFilters.innerHTML='<summary>Filters <span class="browse-filter-count"></span></summary><div class="browse-filter-body"></div>';search.append(searchFilters);searchFilters.lastElementChild.append($('#live-filters'));
 const hint=document.createElement('p');hint.className='browse-hint';hint.textContent='Start with keywords; use Media to choose the format. Other filters narrow loaded results. Keyword coverage varies by provider.';search.append(hint);
 $('#classic-search-filters').onclick=()=>{if(folded){folded=false;paintFold();searchFilters.open=true;}else searchFilters.open=!searchFilters.open;searchFilters.querySelector('summary').focus();};
 $('#classic-search-focus').onclick=()=>{folded=false;paintFold();$('#live-query').focus();};
 const foldKey='folio-search-controls-folded-v1';let folded=false;try{folded=localStorage.getItem(foldKey)==='true';}catch{}
 const foldBar=document.createElement('div');foldBar.className='search-fold-bar';foldBar.innerHTML='<span class="search-fold-summary"></span><button type="button" class="search-fold-toggle" aria-controls="live-form live-filters"></button>';search.prepend(foldBar);
 function paintFold(){search.classList.toggle('is-folded',folded);const toggle=foldBar.querySelector('button');toggle.textContent=folded?'Show search controls':'Collapse search controls';toggle.setAttribute('aria-expanded',String(!folded));const count=(typeof FolioFacets!=='undefined'?FolioFacets.count('search'):0)+['#live-kind','#live-provider','#live-year','#live-genre','#live-platform','#live-owned'].filter(s=>$(s).value).length;foldBar.querySelector('span').textContent=folded?($('#live-query').value.trim()||'Search')+(count?' · '+count+' '+(count===1?'filter':'filters'):'')+($('#live-results').getAttribute('aria-busy')==='true'?' · Searching…':''):'Search & filters';}
 foldBar.querySelector('button').onclick=()=>{folded=!folded;try{localStorage.setItem(foldKey,String(folded));}catch{}paintFold();};
 document.addEventListener('input',paintFold);document.addEventListener('change',paintFold);new MutationObserver(paintFold).observe($('#live-results'),{attributes:true,attributeFilter:['aria-busy']});paintFold();

 function filterCounts(){const libraryCount=(typeof FolioFacets!=='undefined'?FolioFacets.count('library'):0)+(type!=='All media'?1:0)+['#genre-filter','#year-filter'].filter(s=>$(s).value!=='all').length+($('#favorites-only').checked?1:0);filters.querySelector('.browse-filter-count').textContent=libraryCount?`(${libraryCount} active)`:'';const searchCount=(typeof FolioFacets!=='undefined'?FolioFacets.count('search'):0)+['#live-kind','#live-provider','#live-year','#live-genre','#live-platform','#live-owned'].filter(s=>$(s).value).length;searchFilters.querySelector('.browse-filter-count').textContent=searchCount?`(${searchCount} active)`:'';$('#classic-search-filters').setAttribute('aria-expanded',String(searchFilters.open));}
 document.addEventListener('change',filterCounts);document.addEventListener('input',filterCounts);searchFilters.addEventListener('toggle',filterCounts);
 window.addEventListener('storage',e=>{if(e.key!==key)return;try{const next=JSON.parse(e.newValue||'{}');if(next&&typeof next==='object'&&!Array.isArray(next)){store=next;undo=null;render();}}catch{}});
 function scope(){return selectedCollection==='all'?'library':'collection:'+selectedCollection;}
 function ids(){return items.filter(x=>selectedCollection==='all'||collections.find(c=>c.id===selectedCollection)?.members.includes(x.id)).map(x=>x.id);}
 function rows(){return reconcile(store[scope()],ids());}
 function active(){return view!=='catalog'&&view!=='home'&&!collectionSpace&&$('#sort').value==='custom';}
 function commit(next,message,moved){const before=positions();const previous=store[scope()];store[scope()]=next;try{localStorage.setItem(key,JSON.stringify(store));undo={scope:scope(),rows:previous};render();animateOrder(before,moved);$('#layout-status').textContent=message;return true;}catch{if(previous)store[scope()]=previous;else delete store[scope()];toast('Could not save custom order. Browser storage is full.');return false;}}
 function control(action,id,label,text){const button=document.createElement('button');button.type='button';button.dataset.layoutAction=action;button.dataset.layoutId=id;button.setAttribute('aria-label',label);button.title=label;button.textContent=text;return button;}
 function paint(){filterCounts();tools.hidden=!active();$('#layout-undo').hidden=!undo;$('#divider-form').hidden=collectionSpace;const grid=$('#grid');grid.classList.toggle('custom-order',active());if(!active())return;
  const cards=new Map([...grid.querySelectorAll('[data-library-id]')].map(card=>[card.dataset.libraryId,card]));
  const ordered=rows().filter(row=>row.kind==='divider'||cards.has(row.id));
  for(const [index,row] of ordered.entries()){
   let card=cards.get(row.id);if(row.kind==='divider'){card=document.createElement('section');card.className='custom-divider';const title=document.createElement('input');title.value=row.title;title.maxLength=80;title.setAttribute('aria-label','Section title: '+row.title);title.dataset.dividerTitle=row.id;card.append(title);const remove=control('remove',row.id,'Remove divider '+row.title,'×');card.append(remove);}
   if(!card)continue;card.draggable=true;const tile=card.querySelector('.card');if(tile)tile.draggable=true;card.querySelectorAll('img').forEach(img=>img.draggable=false);card.dataset.layoutId=row.id;const controls=document.createElement('div');controls.className='layout-move-controls';const title=row.kind==='divider'?row.title:items.find(x=>x.id===row.id)?.title||'title';const handle=control('drag',row.id,'Move '+title+'; use Alt and arrow keys','⋮⋮');handle.draggable=true;controls.append(handle,control('up',row.id,'Move '+title+' earlier','↑'),control('down',row.id,'Move '+title+' later','↓'));controls.children[1].disabled=index===0;controls.children[2].disabled=index===ordered.length-1;card.append(controls);grid.append(card);
  }
  const end=document.createElement('div');end.className='layout-drop-end';end.dataset.layoutEnd='true';end.textContent='Drop here to move to the end';grid.append(end);
 }
 const previousLibrary=renderLibrary;renderLibrary=function(){previousLibrary();paint();};
 function focusHandle(id){const handle=[...$('#grid').querySelectorAll('[data-layout-action="drag"]')].find(el=>el.dataset.layoutId===id);handle?.focus();}
 function moveBy(id,delta){const list=rows(),visible=[...$('#grid').children].map(el=>el.dataset.layoutId).filter(Boolean),index=visible.indexOf(id),target=visible[index+delta];if(!target)return;if(commit(move(list,id,target,delta>0),'Order saved.',id))focusHandle(id);}
 $('#divider-form').onsubmit=e=>{e.preventDefault();const title=$('#divider-title').value.trim();if(!title)return;const id='divider:'+crypto.randomUUID();if(commit([{id,kind:'divider',title},...rows()],'Section added.')){$('#divider-title').value='';focusHandle(id);}};
 $('#layout-reset').onclick=()=>commit(reconcile([],ids()),'Custom order reset. Use Undo layout change to restore it.');
 $('#layout-undo').onclick=()=>{if(!undo)return;const prior=undo,current=store[prior.scope];if(prior.rows)store[prior.scope]=prior.rows;else delete store[prior.scope];try{localStorage.setItem(key,JSON.stringify(store));undo=null;render();toast('Layout change undone');}catch{store[prior.scope]=current;toast('Could not save layout');}};
 $('#grid').addEventListener('change',e=>{const id=e.target.dataset.dividerTitle;if(id){const title=e.target.value.trim()||'Untitled section';commit(rows().map(r=>r.id===id?{...r,title}:r),'Section renamed.');}});
 $('#grid').addEventListener('click',e=>{const button=e.target.closest('[data-layout-action]');if(!button)return;const {layoutAction:action,layoutId:id}=button.dataset;if(action==='up'||action==='down')moveBy(id,action==='up'?-1:1);if(action==='remove')commit(rows().filter(r=>r.id!==id),'Divider removed. Titles kept.');});
 $('#grid').addEventListener('keydown',e=>{const handle=e.target.closest('[data-layout-action="drag"]');if(handle&&e.altKey&&['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();moveBy(handle.dataset.layoutId,['ArrowUp','ArrowLeft'].includes(e.key)?-1:1);}});
