 function offset(){const nav=document.querySelector('aside'),rect=nav.getBoundingClientRect(),zoom=Number.parseFloat(getComputedStyle(document.documentElement).zoom)||1;document.documentElement.style.setProperty('--browse-top',getComputedStyle(nav).position==='sticky'?Math.max(0,rect.height)/zoom+'px':'0px');document.documentElement.style.setProperty('--browse-height',Math.max(library.getBoundingClientRect().height,search.getBoundingClientRect().height)/zoom+'px');}
